import{_ as t,c as o,o as n,a4 as e}from"./chunks/framework.BYxathSa.js";const P=JSON.parse('{"title":"Q18：HTTP 协议各版本及常用状态码","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q18.md","filePath":"frontend/q18.md","lastUpdated":null}'),r={name:"frontend/q18.md"},s=e('<h1 id="q18-http-协议各版本及常用状态码" tabindex="-1">Q18：HTTP 协议各版本及常用状态码 <a class="header-anchor" href="#q18-http-协议各版本及常用状态码" aria-label="Permalink to &quot;Q18：HTTP 协议各版本及常用状态码&quot;">​</a></h1><p><strong>版本差异</strong></p><ul><li><strong>HTTP/1.0</strong>：需要请求头 <code>Connection: keep-alive</code> 才能保持连接，默认短连接。</li><li><strong>HTTP/1.1</strong>：引入持久连接、管线化（队头阻塞问题仍在）、增加 Host 头、缓存机制增强。</li><li><strong>HTTP/2</strong>：基于二进制分帧，实现多路复用（同连接并发请求/响应，解决队头阻塞）、头部压缩（HPACK）、服务器推送。</li><li><strong>HTTP/3</strong>：基于 QUIC（UDP），0-RTT 握手，彻底解决 TCP 层面的队头阻塞，改进移动网络性能。</li></ul><p><strong>常用状态码</strong></p><ul><li><strong>2xx 成功</strong>：200 成功，201 已创建，204 无内容。</li><li><strong>3xx 重定向</strong>：301 永久移动，302 临时移动，304 未修改（走缓存）。</li><li><strong>4xx 客户端错误</strong>：400 请求语法错误，401 未认证，403 禁止访问，404 未找到，405 方法不允许。</li><li><strong>5xx 服务器错误</strong>：500 内部错误，502 网关错误，503 服务不可用。</li></ul>',5),a=[s];function l(i,_,c,d,T,g){return n(),o("div",null,a)}const h=t(r,[["render",l]]);export{P as __pageData,h as default};
